#include "complete-house-solution-validator.h"

bool charm::v1n7::zebra_puzzle::validate_complete_house_solution(const std::vector<std::vector<std::string>>& houses,std::size_t attribute_count,const std::vector<charm::v1n7::zebra_puzzle::ValuePairClue>& equal_house,const std::vector<charm::v1n7::zebra_puzzle::ValuePairClue>& neighbors){std::map<std::string,std::size_t> location;for(std::size_t h=0;h<houses.size();++h){if(houses[h].size()!=attribute_count)return false;std::set<std::string> row;for(const auto& value:houses[h])if(value.empty()||!row.insert(value).second||!location.emplace(value,h).second)return false;}auto known=[&](const ValuePairClue& c){return location.count(c.first)&&location.count(c.second)&&c.first!=c.second;};for(const auto& c:equal_house)if(!known(c)||location[c.first]!=location[c.second])return false;for(const auto& c:neighbors)if(!known(c)||std::llabs(static_cast<long long>(location[c.first])-static_cast<long long>(location[c.second]))!=1)return false;return true;}
